  "employEWalk": "<a href=\"/\" class=\"text-amber-300 underline\">Home</a> · <a href=\"/chat.html\" class=\"text-amber-300 underline\">Chat</a> · <a href=\"/employ.html\" class=\"text-amber-300 underline\">Employ</a> · <a href=\"/Launch-Ra-Thor.html\" class=\"text-amber-300 underline\">Launch</a> · <a href=\"/micro-moment.html\" class=\"text-amber-300 underline\">Moments</a> · <a href=\"/sovereign-shard.html\" class=\"text-amber-300 underline\">Shard</a> · <a href=\"/web-forge.html\" class=\"text-amber-300 underline\">Forge</a> · <a href=\"/contact.html\" class=\"text-amber-300 underline\">Contact</a> · <a href=\"/privacy.html\" class=\"text-amber-300 underline\">Privacy</a>",
  "employFBody": "AG-SML: personal / research / modest freelance. Commercial / org / revenue → paid license. Use the <a href=\"/contact.html#commercial-inquiry\" class=\"text-amber-300 underline\">commercial inquiry form</a> or write <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>.",
